### 获取元素方法
```java
public class LinkedList<E> {

    // 根据下标从链表上查找元素
    public E get(int index) {
        // 检查下标是否越界
        checkElementIndex(index);
        // 如果没有越界，就返回下标位置那个节点上存储的数据
        return node(index).item;
    }
    Node<E> node(int index) {
        // 如果查找的元素在链表的左半部分，则从头节点开始找。
        if (index < (size >> 1)) {
            // 把第一个元素临时让x保存一下
            Node<E> x = first;
            // 循环index次
            for (int i = 0; i < index; i++)
                x = x.next;
            // 直接返回 x
            return x;
        } else {
            // 如果查找的元素在链表的右半部分，则从尾节点开始找。
            Node<E> x = last;
            // 逆向遍历查找
            for (int i = size - 1; i > index; i--)
                x = x.prev;
            return x;
        }
    }
}
```

### 修改元素方法
```java
public class LinkedList<E> {
    public E set(int index, E element) {
        // 检查下标是否越界
        checkElementIndex(index);
        // 先找到要修改的元素
        Node<E> x = node(index);
        // 先把要修改的值先保存一份，后面返回它
        E oldVal = x.item;
        // 修改
        x.item = element;
        // 返回修改前的数据
        return oldVal;
    }
}
```



### 插入元素方法
```java
public class LinkedList<E> {
     public void add(int index, E element) {
        // 先检查下标是否合法
        checkPositionIndex(index);
        // 如果正好是往末尾添加
        if (index == size)
            // 加到末尾
            linkLast(element);
        else
            // 把新元素插到被查找的元素的前面
            linkBefore(element, node(index));
    }
    void linkBefore(E e, Node<E> succ) {
        // 先把查找到的元素的上一个节点的内存地址保存一份
        final Node<E> pred = succ.prev;
        // 创建新节点
        final Node<E> newNode = new Node<>(pred, e, succ);
        // 新节点作为查找到的节点的上一个节点
        succ.prev = newNode;
        // 如果是空链表
        if (pred == null)
            // 新节点作为头节点
            first = newNode;
        else
            // 不是空链表的话，上一个节点的下一个节点是新增的节点
            pred.next = newNode;
        // 元素+1
        size++;
        modCount++;
    }
}
```



