        return age;
    }

    public void setAge(int age) {
        this.age = age;
    }

    public double getScore() {
        return score;
    }

    public void setScore(double score) {
        this.score = score;
    }

    // 重写toString()方法
    @Override
    public String toString() {
        return "Student{" +
                "name='" + name + '\'' +
                ", age=" + age +
                ", score=" + score +
                '}';
    }
}
```



接下来，我们使用Comparator接口，按照学生的年龄执行升序排序，代码实现如下。

【示例】key为Student类，并且按照年龄执行降序排序

```java
public class Test02 {
    public static void main(String[] args) {
        // 创建TreeMap集合（采用定制排序）
        TreeMap<Student, String> map = new TreeMap<>(new Comparator<Student>() {
            /**
             * 按照学生年龄执行“降序”排序
             */
            @Override
            public int compare(Student stu1, Student stu2) {
                return -Integer.compare(stu1.getAge(), stu2.getAge());
            }
        });
        // 添加键值对
        map.put(new Student("张三", 38, 78.5), "天津");
        map.put(new Student("李四", 20, 99.5), "北京");
        map.put(new Student("王五", 27, 100.0), "北京");
        map.put(new Student("赵六", 18, 59.5), "南京");
        map.put(new Student("王五", 27, 67.0), "上海"); // 此处会覆盖“北京”
        // 使用迭代器来遍历TreeMap集合
        Iterator<Student> iterator = map.keySet().iterator();
        while (iterator.hasNext()) {
            Student key = iterator.next();
            System.out.println("key:" + key + ", value:" + map.get(key));
        }
    }
}
```

当compare()方法返回的结果为0，则意味着key发生了重复，以上案例输出结果如下：

key:Student{name='张三', age=38, score=78.5}, value:天津

key:Student{name='王五', age=27, score=100.0}, value:上海

key:Student{name='李四', age=20, score=99.5}, value:北京

key:Student{name='赵六', age=18, score=59.5}, value:南京



然后，我们继续使用Comparator接口，按照学生的成绩执行升序排序，代码实现如下。

【示例】key为Student类，并且按照成绩执行升序排序 

```java
public class Test02 {
    public static void main(String[] args) {
        // 创建TreeMap集合（采用定制排序）
        TreeMap<Student, String> map = new TreeMap<>(new Comparator<Student>() {
            /**
             * 按照学生成绩执行“升序”排序
             */
            @Override
            public int compare(Student stu1, Student stu2) {
                return Double.compare(stu1.getScore(), stu2.getScore());
            }
        });
        // 添加键值对
        map.put(new Student("张三", 38, 78.5), "天津");
        map.put(new Student("李四", 20, 99.5), "北京");
        map.put(new Student("王五", 27, 100.0), "北京");
        map.put(new Student("赵六", 18, 99.5), "南京");// 此处会覆盖“北京”
        map.put(new Student("王麻子", 27, 67.0), "上海");
        // 使用迭代器来遍历TreeMap集合
        Iterator<Student> iterator = map.keySet().iterator();
        while (iterator.hasNext()) {
            Student key = iterator.next();
            System.out.println("key:" + key + ", value:" + map.get(key));
        }
    }
}
```

当compare()方法返回的结果为0，则意味着key发生了重复，以上案例输出结果如下：

key:Student{name='王麻子', age=27, score=67.0}, value:上海

key:Student{name='张三', age=38, score=78.5}, value:天津

key:Student{name='李四', age=20, score=99.5}, value:南京

key:Student{name='王五', age=27, score=100.0}, value:北京



**使用TreeMap要点：**

1. TreeMap集合内部要做排序，要么使用Comparable接口，要么使用Comparator接口。
2. TreeMap的key不能为null，否则抛出java.lang.NullPointerException异常。



