    public static void main(String[] args) {
        // 实例化TreeSet集合（自然排序）
        TreeSet<String> set = new TreeSet<>();
        // 添加元素
        set.add("cc");
        set.add("aa");
        set.add("bb");
        set.add("dd");
        set.add("bb"); // 元素重复，添加失败
        // 遍历元素
        Iterator<String> iterator = set.iterator();
